async function SWITCH_F() {
  let $1;
  if (isVerb(V.LAMP_ON, V.TURN, V.PUSH, V.MOVE, V.THROW)) {
    if (g.DRIVE_TO_PLOTTER && g.BROWNIAN_SOURCE) {
      move(SPARE_DRIVE, g.HERE);
      move(PLOTTER, g.HERE);
      move(g.BROWNIAN_SOURCE, g.HERE);
      if (g.BROWNIAN_SOURCE == TEA) {
        g.HOLDING_NO_TEA = true;
      }
      if (g.DRIVE_TO_CONTROLS) {
        tell("As you flip the switch, sparks fly from the large receptacle. ");
        if ((await RUNNING$(I_TEA.id)) && (g.TEA_COUNTER > 6)) {
          tell("\"My new control console!\" wails ", D(EDDIE), ". \"This is the thanks I get");
        } else {
          tell("\"Now look what you've done. You've destroyed", S(g.MOP), ". Don't you know it's only for emergencies");
        }
        tell("?\"\n\n");
        g.DRIVE_TO_CONTROLS = false;
        clearFlag(SPARE_DRIVE, NDESCBIT);
        move(LARGE_PLUG, LOCAL_GLOBALS);
        move(LARGE_RECEPTACLE, LOCAL_GLOBALS);
        if ((await RUNNING$(I_TEA.id)) && (g.TEA_COUNTER > 6)) {
          move(TEA, SLOT);
          disable(await INT(I_TEA.id));
          enable(await QUEUE(I_LANDING.id, 24));
          g.FOLLOW_FLAG = 3;
          enable(await QUEUE(I_FOLLOW.id, 2));
          tell("The universe goes crazy for a moment.\n\n", S(g.ANNOUNCEMENT), D(EDDIE), ". The missiles have turned into a sperm whale");
          (await FACTOR("39,745"));
          tell(" The whale is currently plummeting toward", S(g.LOST_PLANET), ". I hope this will teach you to listen to me when I say that legendary lost planets can be dangerous. I am proceeding with the pre-set landing instructions.\"\n\nFord, Zaphod, and ", D(TRILLIAN), " saunter by on their way back to the sauna. \"Good work, kid,\" says Zaphod, slamming you on the back.\n");
          return true;
        } else {
          disable(await INT(I_TEA.id));
          g.SCORE = g.SCORE - 30;
          tell(S(g.ANNOUNCEMENT), D(EDDIE), ". Someone has activated a ", D(SPARE_DRIVE), " at", S(g.MOP), ", moving us 8 billion parsecs away from our destination, adding seven weeks to our trip. As if that isn't bad enough, all 300 members of the Fronurbdi Planetary Senate appeared in the ", D(HATCHWAY));
          (await FACTOR("79,818"));
          tell(" I'm flushing them into space now, but who knows what sort of germs they've dragged into the ship? Everyone should take extra vitamins today.\"\n");
          return true;
        }
      } else if (await RUNNING$(I_TEA.id)) {
        g.DREAMING = true;
        disable(await INT(I_TEA.id));
        (await JIGS_UP("Everything becomes dark! But no, not quite everything ... There's a big bright planet below, just visible behind your mighty tail fin. Air begins rushing by, tickling your snout and dorsal fins ... you suddenly realise that, improbably enough, you've turned yourself into a sperm whale and are plummeting through the atmosphere of a planet! You begin experimenting with your new body, opening and closing your spout and wagging your enormous tail. Just as you are getting used to being a whale, the ground rushes up and hits you at about 200 mph."));
        return true;
      } else {
        if (g.BROWNIAN_SOURCE == TEA) {
          g.DARK_CONTROLLED = true;
        }
        move(HATCH, LOCAL_GLOBALS);
        move(MECHANISM, LOCAL_GLOBALS);
        $1 = await PICK_ONE(g.DARK_ENTRANCES);
        tell(S($1));
        tell("\n\n");
        await GOTO(DARK);
        return true;
      }
    } else {
      tell("Nothing happens.\n");
      return true;
    }
  } else {
    return false;
  }
}

