async function FINISH(repeating = false) {
  crlf();
  if (!repeating) {
    await V_SCORE();
    crlf();
  }
  tell("Would you like to start over, restore a saved position, or end this session of the game?\n(Type RESTART, RESTORE, or QUIT): >");
  await read(g.P_INBUF, g.P_LEXV);
  if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
    await restart();
    tell("Failed.\n");
    return await FINISH(true);
  } else if (eq(get(g.P_LEXV, 1), W.RESTOR)) {
    if (await restore()) {
      tell("Ok.\n");
      return true;
    } else {
      tell("Failed.\n");
      return await FINISH(true);
    }
  } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q)) {
    return await quit();
  } else {
    return await FINISH(true);
  }
}

