async function V_FOOTNOTE() {
  if (!g.PRSO || !(g.PRSO == INTNUM)) {
    tell("Specify a number, as in \"FOOTNOTE 6.\"\n");
    return true;
  } else if (g.P_NUMBER == 1) {
    tell("In case anyone is interested, this quotation is from a letter written by John Keats, and thus he becomes the first major 19th Century British poet to feature in a computer game.\n");
    return true;
  } else if (g.P_NUMBER == 2) {
    tell("Bob Dylan, 1969.\n");
    return true;
  } else if (g.P_NUMBER == 3) {
    tell("A meaningless coincidence.\n");
    return true;
  } else if (g.P_NUMBER == 4) {
    tell("The first single they recorded on their own Apple label, and one of their most successful songs ever.\n");
    return true;
  } else if (g.P_NUMBER == 5) {
    tell("Peacefully for a ", D(BEAST), " that is. Now and then it snorts or rolls over, and the walls shake a bit.\n");
    return true;
  } else if (g.P_NUMBER == 6) {
    tell("That was just an example.\n");
    return true;
  } else if (g.P_NUMBER == 7) {
    g.AWAITING_REPLY = 13;
    enable(await QUEUE(I_REPLY.id, 1));
    return (await NOT_VERY_GOOD("gun"));
  } else if (g.P_NUMBER == 8) {
    g.AWAITING_REPLY = 13;
    enable(await QUEUE(I_REPLY.id, 1));
    return (await NOT_VERY_GOOD("legend"));
  } else if (g.P_NUMBER == 9) {
    tell("Unfortunately, you couldn't hear a word of it, because sound doesn't travel in a vacuum.\n");
    return true;
  } else if (g.P_NUMBER == 10) {
    tell("I guess it isn't all that dangerous a place after all.\n");
    return true;
  } else if (g.P_NUMBER == 11) {
    g.AWAITING_REPLY = 14;
    enable(await QUEUE(I_REPLY.id, 2));
    tell("Isn't it fun reading through all the footnotes?\n");
    return true;
  } else if (g.P_NUMBER == 12) {
    tell("This is the famous recursive footnote (Footnote 12).\n");
    return true;
  } else if (g.P_NUMBER == 13) {
    g.AWAITING_REPLY = 13;
    enable(await QUEUE(I_REPLY.id, 1));
    return (await NOT_VERY_GOOD("autopilot"));
  } else if (g.P_NUMBER == 14) {
    tell(S(g.GUIDE_NAME), " is also the name of a terrific work of interactive fiction by Douglas Adams and S. Eric Meretzky.", S(g.ALREADY_KNOW_THAT), "\n");
    return true;
  } else if (g.P_NUMBER == 15) {
    g.AWAITING_REPLY = 13;
    enable(await QUEUE(I_REPLY.id, 1));
    return (await NOT_VERY_GOOD("banner"));
  } else {
    tell("There is no Footnote ", N(g.P_NUMBER), ".\n");
    return true;
  }
}

