async function V_LOOK_INSIDE() {
  if (hasFlag(g.PRSO, ACTORBIT) && !(g.PRSO == SCREENING_DOOR)) {
    tell("There is nothing special to be seen.\n");
    return true;
  } else if (g.PRSO == SPARE_DRIVE || g.PRSO == THUMB || g.PRSO == PLOTTER) {
    tell("You can't do that.\n");
    return true;
  } else if (hasFlag(g.PRSO, SURFACEBIT)) {
    if (g.PRSO == loc(g.WINNER)) {
      await DESCRIBE_VEHICLE();
      return true;
    } else if (first(g.PRSO)) {
      return await PRINT_CONT(g.PRSO);
    } else {
      tell("There is nothing on");
      await ARTICLE(g.PRSO, true);
      tell(".\n");
      return true;
    }
  } else if (hasFlag(g.PRSO, DOORBIT)) {
    tell("All you can tell is that");
    await ARTICLE(g.PRSO, true);
    tell(" is ");
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("open.");
    } else {
      tell("closed.");
    }
    return crlf();
  } else if (hasFlag(g.PRSO, CONTBIT)) {
    if (g.PRSO == loc(g.WINNER)) {
      await DESCRIBE_VEHICLE();
      return true;
    } else if (await SEE_INSIDE$(g.PRSO)) {
      if (first(g.PRSO)) {
        return await PRINT_CONT(g.PRSO);
      } else {
        tell("It's empty.\n");
        return true;
      }
    } else if (!(hasFlag(g.PRSO, OPENBIT)) && first(g.PRSO)) {
      await PERFORM(V.OPEN, g.PRSO);
      return true;
    } else {
      tell("It seems that");
      await ARTICLE(g.PRSO, true);
      tell(" is closed.\n");
      return true;
    }
  } else {
    tell("You can't do that.\n");
    return true;
  }
}

