async function V_WALK() {
  let pt = 0, pts = 0, str = 0, obj = 0, rm = 0;
  if ((loc(FLEET) == g.HERE) && !(g.PRSO == P.UP || g.PRSO == P.DOWN)) {
    tell("You would be no safer there.\n");
    return true;
  } else if (g.LYING_DOWN) {
    tell(S(g.WHILE_LYING), "\n");
    return true;
  } else if (hasFlag(TOWEL, WORNBIT)) {
    g.BEARINGS_LOST = true;
    tell("You stumble in that direction, but as you can't see where you're going you wander around in circles.");
    if (!(hasFlag(BEAST, MUNGEDBIT))) {
      tell(" The Beast is getting puzzled that something it can't see is stumbling around its lair.", S(g.SLOWLY_DAWNS));
    }
    return crlf();
  } else if (!(g.HERE == MAZE) && (g.IDENTITY_FLAG == ARTHUR) && g.BRAIN_DAMAGED && prob(30)) {
    tell("You notice that you can't remember how to walk. Oddly, as you think about walking, all that comes to mind is an image of");
    await ARTICLE(g.BRAIN_DAMAGED);
    tell(".\n");
    return true;
  } else if (!g.P_WALK_DIR) {
    await PERFORM(V.WALK_TO, g.PRSO);
    return true;
  } else if (pt = getPropAddr(g.HERE, g.PRSO)) {
    if (eq(pts = propSize(pt), UEXIT)) {
      return await GOTO(getb(pt, REXIT));
    } else if (pts == NEXIT) {
      tell(S(get(pt, NEXITSTR)), "\n");
      return M_FATAL;
    } else if (pts == FEXIT) {
      if (rm = await apply(get(pt, FEXITFCN))) {
        return await GOTO(rm);
      } else if ((g.HERE == BRIDGE) && (g.P_WALK_DIR == P.WEST)) {
        return true;
      } else {
        return M_FATAL;
      }
    } else if (pts == CEXIT) {
      if (globalValue(getb(pt, CEXITFLAG))) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, CEXITSTR)) {
        tell(S(str), "\n");
        return M_FATAL;
      } else {
        tell(S(g.CANT_GO), "\n");
        return M_FATAL;
      }
    } else if (pts == DEXIT) {
      if (hasFlag(obj = getb(pt, DEXITOBJ), OPENBIT)) {
        return await GOTO(getb(pt, REXIT));
      } else if (str = get(pt, DEXITSTR)) {
        tell(S(str), "\n");
        g.P_IT_OBJECT = obj;
        return M_FATAL;
      } else {
        tell("The ", D(obj), " is closed.\n");
        g.P_IT_OBJECT = obj;
        return M_FATAL;
      }
    } else {
      return false;
    }
  } else {
    if (g.PRSO == P.OUT || g.PRSO == P.IN) {
      await V_WALK_AROUND();
    } else {
      tell(S(g.CANT_GO), "\n");
    }
    return M_FATAL;
  }
}

