async function I_CAPTAIN() {
  enable(await QUEUE(I_CAPTAIN.id, -1));
  g.CAPTAIN_COUNTER = g.CAPTAIN_COUNTER + 1;
  crlf();
  if (g.CAPTAIN_COUNTER == 1) {
    tell("\"If he's going to read us his poetry,\" mutters Ford, sweating profusely, \"just pray he softens us up with some cudgels first...\"\n\n");
  }
  if (!(await HELD$(BABEL_FISH, PROTAGONIST))) {
    tell("The ", D(VOGON_CAPTAIN), " says, \"O");
    await PRODUCE_GIBBERISH(2);
    if (g.CAPTAIN_COUNTER == 6) {
      return await GUARDS_TO_AIRLOCK();
    } else {
      return crlf();
    }
  } else if (g.CAPTAIN_COUNTER == 1) {
    tell("\"Hello, hitchhikers!\" begins the ", D(VOGON_CAPTAIN), ". \"I've decided to read you a verse of my poetry!\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 2) {
    tell("\"Oh freddled gruntbuggly, thy nacturations are to me!\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 3) {
    tell("\"As plurdled gabbleblotchits on a lurgid bee.\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 4) {
    tell("\"Groop I implore thee, my foonting turlingdromes.\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 5) {
    tell("\"And hooptiously drangle me with crinkly bindlewurdles, or I will rend thee in the gobberwarts with my blurglecruncheon, see if I don't!\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 6) {
    if (g.POEM_ENJOYED) {
      tell("\"You looked like you enjoyed my poem. I think...yes, I think I'll read the NEXT verse, also!\"\n");
      return true;
    } else {
      tell("\"You didn't seem to enjoy my poem at all! Guards, toss them out the airlock!\"");
      return await GUARDS_TO_AIRLOCK();
    }
  } else if (g.CAPTAIN_COUNTER == 7) {
    if (g.LINE_NUMBER == 1 || g.LINE_NUMBER == 2) {
      tell(S(g.LINE_A), "\n");
      return true;
    } else if (g.LINE_NUMBER == 3 || g.LINE_NUMBER == 4) {
      tell(S(g.LINE_B), "\n");
      return true;
    } else {
      tell(S(g.LINE_C), "\n");
      return true;
    }
  } else if (g.CAPTAIN_COUNTER == 8) {
    if (g.LINE_NUMBER == 3 || g.LINE_NUMBER == 5) {
      tell(S(g.LINE_A), "\n");
      return true;
    } else if (g.LINE_NUMBER == 1 || g.LINE_NUMBER == 6) {
      tell(S(g.LINE_B), "\n");
      return true;
    } else {
      tell(S(g.LINE_C), "\n");
      return true;
    }
  } else if (g.CAPTAIN_COUNTER == 9) {
    if (g.LINE_NUMBER == 4 || g.LINE_NUMBER == 6) {
      tell(S(g.LINE_A), "\n");
      return true;
    } else if (g.LINE_NUMBER == 2 || g.LINE_NUMBER == 5) {
      tell(S(g.LINE_B), "\n");
      return true;
    } else {
      tell(S(g.LINE_C), "\n");
      return true;
    }
  } else if (g.CAPTAIN_COUNTER == 10) {
    tell("\"Gerond withoutitude form into formless bloit, why not then? Moose.\"\n");
    return true;
  } else if (g.CAPTAIN_COUNTER == 11) {
    tell("\"Since you have somehow managed to survive two verses of my poetry, I have no choice but to space you. Guards!\"");
    return await GUARDS_TO_AIRLOCK();
  } else {
    return false;
  }
}

async function GUARDS_TO_AIRLOCK() {
  disable(await INT(I_CAPTAIN.id));
  tell(" A guard grabs you and Ford, and drags you toward the hold. Ford whispers, \"Don't worry, I'll think of something!\"\n\n");
  clearFlag(HOLD, TOUCHBIT);
  await GOTO(HOLD);
  clearFlag(FORD, NDESCBIT);
  move(GUARDS, g.HERE);
  move(FORD, g.HERE);
  return enable(await QUEUE(I_FORD.id, 1));
}

async function POETRY_F() {
  if (isVerb(V.ENJOY, V.LISTEN) && (g.CAPTAIN_COUNTER < 2)) {
    tell("The ", D(VOGON_CAPTAIN), " hasn't begun yet!\n");
    return true;
  } else if (isVerb(V.ENJOY)) {
    if (!(await HELD$(BABEL_FISH))) {
      tell("You can't even understand it, let alone enjoy it!\n");
      return true;
    } else if (g.POEM_ENJOYED) {
      g.AWAITING_REPLY = 8;
      enable(await QUEUE(I_REPLY.id, 2));
      tell("Hey, let's not overdo it, okay?\n");
      return true;
    } else {
      g.POEM_ENJOYED = true;
      g.SCORE = g.SCORE + 15;
      tell("You realise that, although the ", D(POETRY), " is indeed astoundingly bad, worse things happen at sea, and in fact, at school. With an effort for which Hercules himself would have patted you on the back, you grit your teeth and enjoy the stuff.\n");
      return true;
    }
  } else if (isVerb(V.LISTEN)) {
    tell("You have no choice. Why not relax and enjoy it?\n");
    return true;
  } else if ((loc(POETRY) == g.HERE) && isVerb(V.BLOCK)) {
    await PERFORM(V.LISTEN, POETRY);
    return true;
  } else if (isVerb(V.READ, V.EXAMINE)) {
    tell("You can't see it from here.\n");
    return true;
  } else {
    return false;
  }
}

