async function AIRLOCK_F(rarg) {
  if (rarg == M_END) {
    g.AIRLOCK_COUNTER = g.AIRLOCK_COUNTER + 1;
    crlf();
    if (g.AIRLOCK_COUNTER == 1) {
      tell("Ford points at the ", D(VOGON_OUTER_DOOR), ". \"In about two minutes, it will open and we'll be ejected into the vacuum of space. But don't panic, I'll think of something.\"\n");
      return true;
    } else if (g.AIRLOCK_COUNTER == 2) {
      tell("Ford is mumbling to himself.\n");
      return true;
    } else if (g.AIRLOCK_COUNTER == 3) {
      tell("Ford produces a pencil and begins scribbling equations on the wall.\n");
      return true;
    } else if (g.AIRLOCK_COUNTER == 4) {
      tell("Ford's eyes light up. \"Do you still have the Electronic Sub-Etha Auto Hitching Thu...\" At that moment, the airlock door opens, and you and Ford are blown out into space.\n\n");
      if (await HELD$(GUIDE)) {
        tell("Your elbow must have struck some key on ", D(GUIDE), " because it begins droning out an entry, coincidentally enough the entry on SPACE. \"", S(g.SPACE_TEXT), "\" (Footnote 9)\n\n");
      }
      tell("Precisely twenty-nine seconds later, you and Ford are scooped up by a passing ship. Gasping for air, you pass out...\n\n");
      g.HEART_PROB = 100;
      return await GOTO(DARK);
    } else {
      return false;
    }
  } else {
    return false;
  }
}

