async function DROP_AT_PARTY() {
  if (!g.ITEM_DROPPED_AT_PARTY) {
    g.ITEM_DROPPED_AT_PARTY = g.PRSO;
    setFlag(HOSTESS, NDESCBIT);
    enable(await QUEUE(I_HOSTESS.id, 3));
  }
  move(g.PRSO, g.HERE);
  if (isVerb(V.DROP)) {
    tell("Dropped.\n");
    return true;
  } else {
    tell("Thrown.\n");
    return true;
  }
}

async function SHRIEK() {
  tell("The hostess lets out a blood-chilling shriek. \"My new carpet!\" ");
  if (isVerb(V.THROW)) {
    tell("Grabbing a shard from your broken ", D(g.PRSO), ", s");
  } else {
    tell("S");
  }
  (await JIGS_UP("he rushes toward you, vengeance burning in her eyes."));
  return true;
}

async function HOSTESS_F() {
  if (HOSTESS == g.WINNER) {
    if (isVerb(V.YES) && (g.AWAITING_REPLY == 4)) {
      g.WINNER = PROTAGONIST;
      await V_YES();
      return g.WINNER = HOSTESS;
    } else if (isVerb(V.NO) && (g.AWAITING_REPLY == 4)) {
      g.WINNER = PROTAGONIST;
      await V_NO();
      return g.WINNER = HOSTESS;
    } else {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.HELLO, HOSTESS);
      return await FUCKING_CLEAR();
    }
  } else if (isVerb(V.HELLO, V.ASK_ABOUT, V.TELL_ABOUT) && (g.PRSO == HOSTESS)) {
    tell("The hostess is delighted to engage in ", D(CONVERSATION));
    (await JIGS_UP(" and pulls you into a corner. Days later, you expire from thirst and exhaustion."));
    return true;
  } else {
    return false;
  }
}

async function I_HOSTESS() {
  enable(await QUEUE(I_HOSTESS.id, -1));
  if (!g.ITEM_DROPPED_AT_PARTY) {
    clearFlag(HOSTESS, TOUCHBIT);
    disable(await INT(I_HOSTESS.id));
    return false;
  }
  move(HOSTESS, g.HERE);
  move(g.ITEM_DROPPED_AT_PARTY, g.HERE);
  crlf();
  if (hasFlag(HOSTESS, TOUCHBIT)) {
    g.AWAITING_REPLY = 4;
    enable(await QUEUE(I_REPLY.id, 2));
    tell("\"Tricia dear,\" says the hostess insistently, \"don't you want your ", D(g.ITEM_DROPPED_AT_PARTY), "?\"\n");
    return true;
  } else {
    setFlag(HOSTESS, TOUCHBIT);
    g.P_IT_OBJECT = g.ITEM_DROPPED_AT_PARTY;
    setFlag(g.ITEM_DROPPED_AT_PARTY, NDESCBIT);
    tell("The hostess, whom you've been avoiding all evening, scurries up with your ", D(g.ITEM_DROPPED_AT_PARTY), ". \"Oh, hello Tricia, how lovely to see you, I think you dropped this, dear.\"\n");
    return true;
  }
}

async function SPEEDBOAT_F(rarg) {
  if (rarg == M_ENTER) {
    g.DREAMING = true;
    g.IDENTITY_FLAG = ZAPHOD;
    move(ZAPHOD, GLOBAL_OBJECTS);
    move(WRENCH, TOOLBOX);
    move(MAGNIFYING_GLASS, TOOLBOX);
    clearFlag(TOOLBOX, OPENBIT);
    await ROB(PROTAGONIST, MEMORIAL);
    move(PROTAGONIST, PILOT_SEAT);
    g.DESTINATION = CHANNEL;
    enable(await QUEUE(I_SPEEDBOAT.id, 2));
    tell("The pain at the back of your eyes is from partying until very late last night, and both your heads are suffering the worst hangover you've ever experienced. You remember formulating a plan to steal ", D(HEART_OF_GOLD), ", but you can't for the life of you remember any details.\n\n");
    return true;
  } else if (rarg == M_LOOK) {
    if (g.BOAT_DOCKED) {
      tell("The boat is resting atop a plume of water. The dais for the dedication ceremonies for ", D(HEART_OF_GOLD), " lies immediately north.\n");
      return true;
    } else {
      tell("You are piloting the ", D(BOAT_OBJECT), ", which features very simple controls, toward the island of France (Footnote 3), where the dedication ceremonies for ", D(HEART_OF_GOLD), " will occur. You are currently steering the boat toward");
      if (g.DESTINATION == CHANNEL) {
        tell(" a ", D(CHANNEL), " between ", D(CLIFF), " and a ", D(SPIRE), ".\n");
        return true;
      } else {
        await ARTICLE(g.DESTINATION);
        tell(".\n");
        return true;
      }
    }
  } else {
    return false;
  }
}

async function I_SPEEDBOAT() {
  g.BOAT_COUNTER = g.BOAT_COUNTER + 1;
  enable(await QUEUE(I_SPEEDBOAT.id, -1));
  if (g.DESTINATION == CLIFF || g.DESTINATION == SPIRE) {
    g.CRASH_COUNTER = g.CRASH_COUNTER + 1;
    if (g.CRASH_COUNTER == 4) {
      g.BOAT_DOCKED = true;
      disable(await INT(I_SPEEDBOAT.id));
      tell("\nSuddenly, the autopilot leaps to life, steering the boat away from the ", D(g.DESTINATION), ". The crowd gathered for the dedication oohs and aahs as the boat swerves through the ", D(CHANNEL), ". As it reaches the base of the ", D(CLIFF), " a plume of water forms under it, sending it higher and higher. The crowd bursts into applause as the boat reaches the top of the cliff, just south of the ceremonial dais.\n");
      return true;
    }
  }
  if (isVerb(V.STEER, V.POINT)) {
    return false;
  }
  if (isVerb(V.AGAIN) && (g.L_PRSA == V.STEER || g.L_PRSA == V.POINT)) {
    return false;
  }
  crlf();
  if (g.BOAT_COUNTER < 7) {
    tell("You continue to steer toward the ", D(g.DESTINATION), ".\n");
    return true;
  } else {
    disable(await INT(I_SPEEDBOAT.id));
    tell("You almost make it through the ", D(CHANNEL), " but the turbulent waters push the boat toward the rocks. The ", D(AUTOPILOT_BUTTON));
    tell(" lights up and an ", S(g.EYE_STALK));
    (await JIGS_UP("but a split-second later the boat smashes into the rocks."));
    return true;
  }
}

async function BOAT_OBJECT_F() {
  if (isVerb(V.STEER) && (g.PRSO == BOAT_OBJECT)) {
    if (g.BOAT_DOCKED) {
      tell("You've already reached your destination!\n");
      return true;
    } else if (g.PRSI == g.DESTINATION) {
      tell("You already ARE steering the boat toward the ", D(g.DESTINATION), ".\n");
      return true;
    } else if (!(g.PRSI == CLIFF || g.PRSI == SPIRE || g.PRSI == CHANNEL)) {
      tell("You can't steer the boat toward");
      await ARTICLE(g.PRSI, true);
      tell("!\n");
      return true;
    } else {
      g.DESTINATION = g.PRSI;
      if (g.BOAT_COUNTER > 3) {
        g.BOAT_COUNTER = 3;
      }
      tell("The boat is now heading straight at the ", D(g.DESTINATION), ".\n");
      return true;
    }
  } else if (isVerb(V.EXIT, V.LEAVE, V.DISEMBARK, V.THROUGH)) {
    if (g.BOAT_DOCKED) {
      return await DO_WALK(P.NORTH);
    } else {
      tell(S(g.DONT_MIX), "\n");
      return true;
    }
  } else {
    return false;
  }
}

