async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0, x = false;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("Those things aren't here!\n");
    return true;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
  } else {
    tbl = g.P_PRSI;
    prso$ = false;
  }
  if (prso$) {
    if ((g.PRSA == V.FIND || g.PRSA == V.FOLLOW || g.PRSA == V.CALL) || (g.PRSA == V.WHAT || g.PRSA == V.WHERE || g.PRSA == V.WHO) || (g.PRSA == V.WAIT_FOR || g.PRSA == V.WALK_TO || g.PRSA == V.WHAT_ABOUT) || (g.PRSA == V.I_AM || g.PRSA == V.CARVE || g.PRSA == V.CALL_WITH)) {
      x = true;
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return true;
        }
      } else {
        return false;
      }
    }
  } else {
    if ((g.PRSA == V.ASK_ABOUT || g.PRSA == V.ASK_FOR || g.PRSA == V.TELL_ABOUT) || (g.PRSA == V.MY_NAME)) {
      x = true;
      if (obj = await FIND_NOT_HERE(tbl, prso$)) {
        if (!(obj == NOT_HERE_OBJECT)) {
          return true;
        }
      } else {
        return false;
      }
    }
  }
  if (x) {
    tell("You'll have to be more specific, I'm afraid.\n");
  } else if (g.WINNER == PROTAGONIST) {
    tell("You can't ");
    if (g.P_XNAM == W.POEM || g.P_XNAM == W.POETRY || g.P_XNAM == W.CONVER) {
      tell("hear");
    } else {
      tell("see");
    }
    if (!(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!\n");
  } else if (((g.WINNER == FORD) && g.FORD_SLEEPING) || ((g.WINNER == BEAST) && hasFlag(BEAST, MUNGEDBIT))) {
    return false;
  } else {
    tell("Looking confused,");
    await ARTICLE(g.WINNER, true);
    tell(" says, \"I don't see");
    if (!(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!\"\n");
  }
  return await FUCKING_CLEAR();
}

async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0;
  m_f = await MOBY_FIND(tbl);
  if (1 == m_f) {
    if (prso$) {
      g.PRSO = g.P_MOBY_FOUND;
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    return false;
  } else if (g.P_XNAM == W.FLUFF) {
    if (prso$) {
      g.PRSO = POCKET_FLUFF;
    } else {
      g.PRSI = POCKET_FLUFF;
    }
    return false;
  } else if (g.P_XNAM == W.TOOL || g.P_XNAM == W.TOOLS) {
    if (prso$) {
      g.PRSO = TWEEZERS;
    } else {
      g.PRSI = TWEEZERS;
    }
    return false;
  } else {
    return NOT_HERE_OBJECT;
  }
}

async function NOT_HERE_PRINT(prso$) {
  if (g.P_OFLAG) {
    if (g.P_XADJ) {
      tell(" ");
      printB(g.P_XADJN);
    }
    if (g.P_XNAM) {
      tell(" ");
      return printB(g.P_XNAM);
    } else {
      return false;
    }
  } else if (prso$) {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC1), get(g.P_ITBL, P_NC1L), false);
  } else {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC2), get(g.P_ITBL, P_NC2L), false);
  }
}

async function LIGHT_F() {
  if (((loc(FLEET) == g.HERE) || (g.HERE == AIRLOCK || g.HERE == INSIDE_WHALE)) && (await VISIBLE$(THUMB))) {
    if (LIGHT == g.PRSI) {
      await PERFORM(g.PRSA, g.PRSO, THUMB);
      return true;
    } else {
      await PERFORM(g.PRSA, THUMB, g.PRSI);
      return true;
    }
  } else if (g.HERE == GALLEY) {
    return await UNIMPORTANT_THING_F();
  } else if ((LIGHT == g.PRSO) && isVerb(V.FIND, V.FOLLOW, V.WHAT, V.WHERE, V.WALK_TO, V.WHAT_ABOUT)) {
    return false;
  } else if ((LIGHT == g.PRSI) && isVerb(V.ASK_ABOUT, V.TELL_ABOUT)) {
    return false;
  } else if (!(g.HERE == BEDROOM)) {
    return await CANT_SEE(LIGHT);
  } else if (isVerb(V.LAMP_ON)) {
    if (hasFlag(g.HERE, ONBIT)) {
      tell("It is.\n");
      return true;
    } else {
      g.LIT = true;
      setFlag(g.HERE, ONBIT);
      setFlag(DARK_OBJECT, DARKBIT);
      move(DARK_OBJECT, DARK);
      tell("Good start to the day. Pity it's going to be the worst one of your life. The light is now on.\n\n");
      return await V_LOOK();
    }
  } else if (isVerb(V.LAMP_OFF)) {
    return await V_DIG();
  } else {
    return false;
  }
}

