async function ME_F() {
  let olit = 0;
  if (isVerb(V.TELL)) {
    tell("Talking to yourself is a sign of impending mental collapse.\n");
    return await FUCKING_CLEAR();
  } else if (isVerb(V.LISTEN)) {
    tell("Yes?\n");
    return true;
  } else if (isVerb(V.ALARM)) {
    tell(S(g.YOU_ARE), "\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == ME)) {
    if ((loc(g.PRSO) == PROTAGONIST) && !(g.PRSO == NO_TEA || g.PRSO == BABEL_FISH)) {
      return await PRE_TAKE();
    } else {
      await PERFORM(V.TAKE, g.PRSO);
      return true;
    }
  } else if (isVerb(V.MOVE)) {
    return await V_WALK_AROUND();
  } else if (isVerb(V.SEARCH)) {
    await V_INVENTORY();
    return true;
  } else if (isVerb(V.KILL, V.MUNG) || (isVerb(V.SHOOT) && (g.PRSI == BLASTER))) {
    (await JIGS_UP("Done."));
    return true;
  } else if (isVerb(V.FIND)) {
    tell("You're right here!\n");
    return true;
  } else if (isVerb(V.WHO)) {
    tell("You are ", D(g.IDENTITY_FLAG), ".\n");
    return true;
  } else if (isVerb(V.EXAMINE) && (g.HERE == MAZE)) {
    tell("You look perfectly normal (except that you're two microns tall).\n");
    return true;
  } else if (isVerb(V.PULL_TOGETHER)) {
    tell(S(g.ZEN), "\n");
    return true;
  } else if (isVerb(V.FOLLOW)) {
    tell("I'd like to, but like most computers I don't have legs.\n");
    return true;
  } else {
    return false;
  }
}

