async function GUARDS_F() {
  if (GUARDS == g.WINNER) {
    if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.ASK_ABOUT, GUARDS, g.PRSI);
      g.WINNER = GUARDS;
      return true;
    } else if (isVerb(V.HELLO)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.HELLO, GUARDS);
      g.WINNER = GUARDS;
      return true;
    } else if (g.HERE == DAIS) {
      if (((loc(RIFLES) == GUARDS) && isVerb(V.SHOOT) && g.DONT_FLAG) || ((loc(RIFLES) == GUARDS) && isVerb(V.DROP) && (g.PRSO == RIFLES))) {
        clearFlag(RIFLES, NDESCBIT);
        enable(await QUEUE(I_GUARDS.id, 8));
        move(RIFLES, g.HERE);
        setFlag(RIFLES, TAKEBIT);
        setFlag(RIFLES, TRYTAKEBIT);
        tell("The guards hesitate, then toss their ", D(RIFLES), "s into a pile in front of you.\n");
        return true;
      } else if (isVerb(V.SHOOT)) {
        if (loc(RIFLES) == GUARDS) {
          return (await JIGS_UP("The air becomes thick with photon beams."));
        } else {
          tell("Someone around here is being very stupid. Let's say it's the guards, since they're only fictitious characters and therefore not potential Infocom customers. The poor fictitious saps don't understand how they can shoot without rifles.\n");
          return true;
        }
      } else if (isVerb(V.TAKE) && (g.PRSO == RIFLES)) {
        if (loc(RIFLES) == GUARDS) {
          tell("\"We already have them!\"\n");
          return true;
        } else {
          move(RIFLES, GUARDS);
          enable(await QUEUE(I_GUARDS.id, 5));
          tell("They do so.\n");
          return true;
        }
      } else if (isVerb(V.LEAVE)) {
        tell("\"We can't leave while you're in trouble, Mr. President!\"\n");
        return true;
      } else {
        tell("You have failed to issue one of the small set of commands that the guards' military intelligences are trained to understand.\n");
        return await FUCKING_CLEAR();
      }
    } else {
      if (await HELD$(BABEL_FISH, PROTAGONIST)) {
        tell("\"Resistance is useless!\"\n");
      } else {
        tell("\"I");
        await PRODUCE_GIBBERISH(1);
        crlf();
      }
      return await FUCKING_CLEAR();
    }
  } else if ((g.HERE == CAPTAINS_QUARTERS) && isVerb(V.TELL, V.HELLO, V.THANK)) {
    await PERFORM(V.TELL, VOGON_CAPTAIN);
    return true;
  } else if ((g.HERE == CAPTAINS_QUARTERS) && (isVerb(V.ASK_ABOUT, V.ASK_FOR) && (GUARDS == g.PRSO))) {
    await PERFORM(V.TELL, VOGON_CAPTAIN);
    return true;
  } else if (isVerb(V.EXAMINE) && (loc(RIFLES) == GUARDS)) {
    tell("They're holding ", D(RIFLES), "s.\n");
    return true;
  } else if ((g.HERE == DAIS) && isVerb(V.SHOOT)) {
    if (await BLASTER_HOLD()) {
      return true;
    }
    tell(S(g.GUARDS_REALIZE));
    (await JIGS_UP("Although you incinerate many, other guards arrive and incinerate you."));
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSO == BLASTER)) {
    tell("The guards are more than glad to disarm you. They");
    await GUARD_DEATH();
    return true;
  } else if (isVerb(V.COUNT)) {
    if (g.HERE == HOLD) {
      tell("One.\n");
      return true;
    } else if (g.HERE == CAPTAINS_QUARTERS) {
      tell("Several.\n");
      return true;
    } else {
      tell("Many.\n");
      return true;
    }
  } else {
    return false;
  }
}

