async function DONT_F() {
  if (isVerb(V.PANIC)) {
    if (prob(50)) {
      tell("Very clever. It looks like there's a lot you should be panicking about.\n");
      return true;
    } else {
      tell("Why not? Your position appears quite hopeless.\n");
      return true;
    }
  } else if (isVerb(V.LOOK)) {
    g.DONT_FLAG = false;
    await PERFORM(V.CLOSE, EYES);
    return true;
  } else if (isVerb(V.WAIT)) {
    tell("Time doesn't pass...\n");
    return true;
  } else if (isVerb(V.TAKE)) {
    tell("Not taken.\n");
    return true;
  } else if (isVerb(V.LISTEN) && (await VISIBLE$(POETRY))) {
    g.DONT_FLAG = false;
    await PERFORM(V.LISTEN, POETRY);
    return true;
  } else {
    tell("Not done.\n");
    return true;
  }
}

async function DARK_F(rarg) {
  if (rarg == M_ENTER) {
    putProp(PROTAGONIST, P.ACTION, DARK_FUNCTION.id);
    await ROB(PROTAGONIST, DARK_OBJECT);
    setFlag(CONVERSATION, INVISIBLE);
    g.DREAMING = false;
    g.LYING_DOWN = false;
    loop1: for (;;) {
      if (prob(g.HEART_PROB)) {
        g.HEART_PROB = 0;
        g.VOGON_PROB = 10;
        g.DARK_FLAG = ENTRY_BAY;
        g.CURRENT_EXIT = 3;
      } else if (prob(g.VOGON_PROB)) {
        g.VOGON_PROB = 0;
        g.HEART_PROB = 100;
        g.DARK_FLAG = HOLD;
        g.CURRENT_EXIT = 0;
      } else if (prob(g.TRAAL_PROB)) {
        if (!(g.TRAAL_PROB == 10)) {
          g.TRAAL_PROB = 10;
          g.TRILLIAN_PROB = 25;
          g.FORD_PROB = 25;
          g.ZAPHOD_PROB = 25;
        }
        g.DARK_FLAG = LAIR;
        g.CURRENT_EXIT = 4;
      } else if (prob(g.TRILLIAN_PROB)) {
        g.TRILLIAN_PROB = 10;
        g.DARK_FLAG = LIVING_ROOM;
        g.CURRENT_EXIT = 2;
      } else if (prob(g.FORD_PROB)) {
        g.FORD_PROB = 10;
        g.DARK_FLAG = COUNTRY_LANE;
        g.CURRENT_EXIT = 1;
      } else if (prob(g.ZAPHOD_PROB)) {
        g.ZAPHOD_PROB = 10;
        g.DARK_FLAG = SPEEDBOAT;
        g.CURRENT_EXIT = 5;
      } else if (prob(g.FLEET_PROB)) {
        g.FLEET_PROB = 10;
        g.DARK_FLAG = WAR_CHAMBER;
        g.CURRENT_EXIT = 7;
      } else if (prob(g.WHALE_PROB)) {
        tell("Bug #60\n");
        g.DARK_FLAG = INSIDE_WHALE;
        g.CURRENT_EXIT = 6;
      }
      if (g.DARK_FLAG) {
        break loop1;
      }
    }
    return false;
  } else if (rarg == M_LOOK) {
    return true;
  } else {
    return false;
  }
}

async function DARK_FUNCTION() {
  if (isVerb(V.QUIT, V.RESTART, V.RESTORE, V.SCORE, V.VERSION, V.SAVE, V.AGAIN, V.HELP, V.VERBOSE, V.BRIEF, V.SUPER_BRIEF, V.SCRIPT, V.UNSCRIPT, V.FOOTNOTE)) {
    return false;
  } else if (g.DONT_FLAG) {
    return false;
  } else if (isVerb(V.PANIC, V.YELL)) {
    tell("You yell as loudly as you can, but no sound emerges.\n");
    return true;
  } else if (isVerb(V.RELAX) || (isVerb(V.ENJOY) && (g.PRSO == DARK_OBJECT))) {
    tell("You achieve a state of Negative Capability, and are able to be in uncertainties, mysteries, doubts, without any irritable searching after fact and reason (Footnote 1).\n");
    return true;
  } else if ((g.DARK_FLAG == ENTRY_BAY || g.DARK_FLAG == WAR_CHAMBER) && isVerb(V.LISTEN) && (g.PRSO == DARK_OBJECT) && (await MISSING$())) {
    move(STAR_DRIVE, g.HERE);
    g.P_IT_OBJECT = STAR_DRIVE;
    tell("You hear the deep and distant hum of a ", D(STAR_DRIVE), " coming from far ");
    if (g.DARK_FLAG == ENTRY_BAY) {
      tell("above");
    } else {
      tell("below");
    }
    tell(". There is an exit to port.\n");
    return true;
  } else if (isVerb(V.WALK) && (await MISSING$()) && (g.DARK_FLAG == WAR_CHAMBER || g.DARK_FLAG == ENTRY_BAY) && (loc(STAR_DRIVE) == g.HERE)) {
    if (g.PRSO == P.SOUTH) {
      if (g.LYING_COUNTER < 4) {
        tell(S(g.LYING_ABOUT_EXIT));
      }
      tell("You emerge from a small doorway...");
      return await LEAVE_DARK();
    } else {
      tell(S(g.CANT_GO));
      if (g.PRSO == P.WEST) {
        g.LYING_COUNTER = g.LYING_COUNTER + 1;
        if (g.LYING_COUNTER == 4) {
          tell(" ", S(g.LYING_ABOUT_EXIT), "There is an exit aft...");
        }
      }
      return crlf();
    }
  } else if (((g.PRSO == STAR_DRIVE) || (g.PRSI == STAR_DRIVE)) && !(isVerb(V.WALK))) {
    if (!(g.DARK_FLAG == ENTRY_BAY || g.DARK_FLAG == WAR_CHAMBER)) {
      return await CANT_SEE(STAR_DRIVE);
    } else if (isVerb(V.LISTEN)) {
      tell("The sound comes from far ");
      if (g.DARK_FLAG == ENTRY_BAY) {
        tell("above");
      } else {
        tell("below");
      }
      tell(".\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.DARK_FLAG == COUNTRY_LANE || g.DARK_FLAG == SPEEDBOAT) && isVerb(V.EXAMINE) && (g.PRSO == DARK_OBJECT) && (await MISSING$())) {
    move(PAINFUL_LIGHT, g.HERE);
    g.P_IT_OBJECT = PAINFUL_LIGHT;
    tell("You see a painfully bright light that stabs at the ");
    if (g.DARK_FLAG == COUNTRY_LANE) {
      tell("front");
    } else {
      tell("back");
    }
    tell(" of your eyes.\n");
    return true;
  } else if (((g.PRSO == PAINFUL_LIGHT) || (g.PRSI == PAINFUL_LIGHT)) && !(isVerb(V.WALK))) {
    if (!(g.DARK_FLAG == SPEEDBOAT || g.DARK_FLAG == COUNTRY_LANE)) {
      return await CANT_SEE(PAINFUL_LIGHT);
    } else if (isVerb(V.EXAMINE)) {
      tell("The light resolves itself into the bright ");
      if (g.DARK_FLAG == COUNTRY_LANE) {
        tell("yellow Sun of Earth");
      } else {
        tell("orange Sun of ", D(DAMOGRAN));
      }
      tell(".");
      return await LEAVE_DARK();
    } else {
      return false;
    }
  } else if ((g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE) && isVerb(V.RUB) && (g.PRSO == DARK_OBJECT) && (await MISSING$())) {
    move(LIQUID, g.HERE);
    g.P_IT_OBJECT = LIQUID;
    tell("It does feel a bit ");
    if (g.DARK_FLAG == LIVING_ROOM) {
      tell("cold");
    } else {
      tell("warm");
    }
    tell(" and wet and squishy. There seems to be some liquid at your fingertips.\n");
    return true;
  } else if (((g.PRSO == LIQUID) || (g.PRSI == LIQUID)) && !(isVerb(V.WALK))) {
    if (!(g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE)) {
      return await CANT_SEE(LIQUID);
    } else if (g.DARK_FLAG == LIVING_ROOM) {
      if (isVerb(V.EXAMINE, V.RUB)) {
        tell("It seems coldish.\n");
        return true;
      } else if (isVerb(V.TASTE, V.DRINK)) {
        tell("It tastes just like wine. In fact, you realise with growing embarrassment that ", D(HANDS), " is sitting in a ", D(WINE), ".");
        return await LEAVE_DARK();
      } else {
        return false;
      }
    } else if (g.DARK_FLAG == INSIDE_WHALE) {
      if (isVerb(V.EXAMINE, V.RUB)) {
        tell("It seems warmish.\n");
        return true;
      } else if (isVerb(V.TASTE, V.DRINK)) {
        tell("Yucchhh! You are jerked to your senses by the realisation that you are licking the lining of a whale's stomach.");
        return await LEAVE_DARK();
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if ((g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR) && isVerb(V.SMELL) && (g.PRSO == DARK_OBJECT) && (await MISSING$())) {
    move(SHADOW, g.HERE);
    g.P_IT_OBJECT = SHADOW;
    tell("It does smell a bit. There's something pungent ");
    if (g.DARK_FLAG == HOLD) {
      tell("being waved");
    } else {
      tell("waving");
    }
    tell(" under your nose. Your head begins to clear. You can make out a shadow moving in the dark.\n");
    return true;
  } else if (((g.PRSO == SHADOW) || (g.PRSI == SHADOW)) && !(isVerb(V.WALK))) {
    if (!(g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR)) {
      return await CANT_SEE(SHADOW);
    } else if (isVerb(V.EXAMINE)) {
      tell("The shadow is vaguely ");
      await BEAST_GUARD_FORD();
      tell("-shaped.");
      return await LEAVE_DARK();
    } else if (isVerb(V.RUB)) {
      tell("The shadow turns out to be a solid object of a ");
      await BEAST_GUARD_FORD();
      tell("-like nature.");
      return await LEAVE_DARK();
    } else if (isVerb(V.SMELL)) {
      tell("The shadow has a sort of ");
      await BEAST_GUARD_FORD();
      tell("y smell to it.");
      return await LEAVE_DARK();
    } else {
      return false;
    }
  } else {
    g.DARK_COUNTER = g.DARK_COUNTER + 1;
    if (g.DARK_CONTROLLED) {
      g.CURRENT_EXIT = g.CURRENT_EXIT + 1;
      if (g.CURRENT_EXIT == 8) {
        g.CURRENT_EXIT = 0;
      }
      g.DARK_FLAG = get(g.DARK_EXIT_TABLE, g.CURRENT_EXIT);
    }
    if (isVerb(V.LOOK)) {
      tell("Dark\n");
    }
    if (prob(25)) {
      await DARK_ONE();
      await FUCKING_CLEAR();
    } else if (prob(33)) {
      await DARK_TWO();
      await FUCKING_CLEAR();
    } else if (prob(50)) {
      await DARK_THREE();
      await FUCKING_CLEAR();
    } else {
      await DARK_FOUR();
      await FUCKING_CLEAR();
    }
    if (g.DARK_COUNTER == 18) {
      tell("\nWhen will you come to your senses and solve this puzzle?\n");
      return true;
    } else if (g.DARK_COUNTER == 33) {
      tell("\n4 out of 5 sensitive people solve this puzzle right away.\n");
      return true;
    } else if (g.DARK_COUNTER == 48) {
      tell("\nDon't count your senses before they hatch.\n");
      return true;
    } else if ((g.DARK_COUNTER == 63) && (g.DARK_FLAG == HOLD)) {
      tell("\nSomething stinks around here, and I'm not just talking about your puzzle-solving ability!\n");
      return true;
    } else {
      return true;
    }
  }
}

async function LEAVE_DARK() {
  crlf();
  crlf();
  putProp(PROTAGONIST, P.ACTION, PROTAGONIST_F.id);
  g.DARK_COUNTER = 0;
  g.LYING_COUNTER = 0;
  g.DARK_CONTROLLED = false;
  await ROB(DARK_OBJECT, PROTAGONIST);
  await ROB(MEMORIAL, PROTAGONIST);
  move(SHADOW, LOCAL_GLOBALS);
  move(PAINFUL_LIGHT, LOCAL_GLOBALS);
  move(LIQUID, LOCAL_GLOBALS);
  move(STAR_DRIVE, LOCAL_GLOBALS);
  if (g.FLUFF_TO_GOWN) {
    move(SATCHEL_FLUFF, GOWN);
    g.FLUFF_TO_GOWN = false;
  }
  if ((g.DARK_FLAG == WAR_CHAMBER) && hasFlag(WAR_CHAMBER, REVISITBIT)) {
    enable(await QUEUE(I_BRAIN_DEATH.id, 6));
    g.HERE = await META_LOC(SPARE_DRIVE);
    move(PROTAGONIST, g.HERE);
    move(NAME, g.HERE);
    g.GUTS_ROOM = g.HERE;
    tell("There is a violent explosion around you, leaving you standing in");
    await ARTICLE(g.HERE, true);
    tell(". ");
    await PERFORM(V.EXAMINE, GROUND);
    tell("\nApparently, you just materialised inside your own brain. This is very very very nasty. You have two choices: quit now, or experience this materialisation from the other end, in about five turns.\n");
  } else if ((g.DARK_FLAG == SPEEDBOAT) && hasFlag(SPEEDBOAT, REVISITBIT)) {
    await GOTO(DAIS);
  } else {
    if (!(g.DARK_FLAG == ENTRY_BAY)) {
      move(MAIN_DRIVE, LOCAL_GLOBALS);
    }
    await GOTO(g.DARK_FLAG);
  }
  g.DARK_FLAG = false;
  return true;
}

async function MISSING$() {
  if (g.DARK_CONTROLLED || (g.DARK_COUNTER > 3)) {
    return true;
  } else {
    return false;
  }
}

async function DARK_ONE() {
  tell("You can ");
  if (!((await MISSING$()) && (g.DARK_FLAG == WAR_CHAMBER || g.DARK_FLAG == ENTRY_BAY))) {
    tell("hear nothing, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR))) {
    tell("smell nothing, ");
  }
  tell("taste nothing, ");
  if (!((await MISSING$()) && (g.DARK_FLAG == COUNTRY_LANE || g.DARK_FLAG == SPEEDBOAT))) {
    tell("see nothing, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE))) {
    tell("feel nothing, ");
  }
  tell("and are not even certain who you are.\n");
  return true;
}

async function DARK_TWO() {
  tell("You can ");
  if (!((await MISSING$()) && (g.DARK_FLAG == COUNTRY_LANE || g.DARK_FLAG == SPEEDBOAT))) {
    tell("see nothing, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE))) {
    tell("feel nothing, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == WAR_CHAMBER || g.DARK_FLAG == ENTRY_BAY))) {
    tell("hear nothing, ");
  }
  tell("taste nothing, ");
  if (!((await MISSING$()) && (g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR))) {
    tell("smell nothing, ");
  }
  tell("and are not entirely certain who you are.\n");
  return true;
}

async function DARK_THREE() {
  tell("You can't ");
  if (!((await MISSING$()) && (g.DARK_FLAG == WAR_CHAMBER || g.DARK_FLAG == ENTRY_BAY))) {
    tell("hear anything, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == COUNTRY_LANE || g.DARK_FLAG == SPEEDBOAT))) {
    tell("see anything, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR))) {
    tell("smell anything, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE))) {
    tell("feel anything, ");
  }
  tell("or taste anything, and do not even know where you are or who you are or how you got there.\n");
  return true;
}

async function DARK_FOUR() {
  tell("There's nothing you can taste, ");
  if (!((await MISSING$()) && (g.DARK_FLAG == COUNTRY_LANE || g.DARK_FLAG == SPEEDBOAT))) {
    tell("nothing you can see, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == WAR_CHAMBER || g.DARK_FLAG == ENTRY_BAY))) {
    tell("nothing you can hear, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == LIVING_ROOM || g.DARK_FLAG == INSIDE_WHALE))) {
    tell("nothing you can feel, ");
  }
  if (!((await MISSING$()) && (g.DARK_FLAG == HOLD || g.DARK_FLAG == LAIR))) {
    tell("nothing you can smell, ");
  }
  tell("you do not even know who you are.\n");
  return true;
}

async function BEAST_GUARD_FORD() {
  if (g.DARK_FLAG == LAIR) {
    tell("Bugblatter Beast");
    return true;
  } else if (hasFlag(HOLD, REVISITBIT)) {
    tell("guard");
    return true;
  } else {
    tell(D(FORD));
    return true;
  }
}

async function I_BRAIN_DEATH() {
  tell("The ", D(ARTHUR));
  (await JIGS_UP(" of five turns ago suddenly materialises inside your brain. There is an incredibly nasty cracking, scrunching noise, and blood and bone fly everywhere as your head, to be perfectly frank about this, explodes. We did warn you."));
  return true;
}

async function TOOTHBRUSH_F() {
  if (isVerb(V.TAKE) && !(hasFlag(TOOTHBRUSH, TOUCHBIT))) {
    move(TOOTHBRUSH, PROTAGONIST);
    setFlag(TOOTHBRUSH, TOUCHBIT);
    clearFlag(TOOTHBRUSH, TRYTAKEBIT);
    tell("As you pick up the ", D(TOOTHBRUSH), " a tree outside the window collapses. There is no causal relationship between these two events.");
    if (hasFlag(PHONE, TOUCHBIT)) {
      await TWO_TREES();
    }
    return crlf();
  } else {
    return false;
  }
}

async function LIQUID_SPILL() {
  if (g.PRSI == FLOWERPOT || g.PRSI == PLANT) {
    await PERFORM(V.WATER, g.PRSI, g.PRSO);
    return true;
  } else {
    move(g.PRSO, LOCAL_GLOBALS);
    if (g.PRSO == g.BROWNIAN_SOURCE) {
      g.BROWNIAN_SOURCE = false;
    } else if (g.PRSO == g.PANEL_BLOCKER) {
      g.PANEL_BLOCKER = false;
    }
    tell("It spills all over and then evaporates.");
    if (g.PRSO == MINERAL_WATER) {
      (await ANTI_LITTER("bottle"));
    } else {
      (await ANTI_LITTER("cup"));
    }
    return crlf();
  }
}

async function ANTI_LITTER(string) {
  tell(" The ", S(string), " itself vaporises, part of the Galactic Anti-Litter Program.");
  return true;
}

async function TEA_DESCFCN(x = 0) {
  return await DESCRIBE_DRINK(TEA);
}

async function DESCRIBE_DRINK(drink) {
  tell("There is a nice, hot cup of ", D(drink), " here.\n");
  return true;
}

async function TEA_F() {
  if (isVerb(V.TAKE) && (g.PRSO == TEA)) {
    move(TEA, PROTAGONIST);
    g.HOLDING_NO_TEA = false;
    tell("no tea: Dropped.\n");
    return true;
  } else if (isVerb(V.DROP)) {
    move(TEA, g.HERE);
    if (g.HERE == ACCESS_SPACE) {
      g.HOLDING_NO_TEA = true;
      return await V_DROP();
    } else if (g.HOLDING_NO_TEA) {
      tell("Dropped.\n");
      return true;
    } else {
      g.HOLDING_NO_TEA = true;
      tell("no tea: Taken.\n");
      return true;
    }
  } else if (isVerb(V.DRINK, V.ENJOY, V.DRINK_FROM)) {
    if (!(await HELD$(g.PRSO))) {
      tell(S(g.NOT_HOLDING), " the cup!\n");
      return true;
    }
    g.SCORE = g.SCORE + 100;
    move(TEA, LOCAL_GLOBALS);
    g.HOLDING_NO_TEA = true;
    if (TEA == g.BROWNIAN_SOURCE) {
      g.BROWNIAN_SOURCE = false;
    }
    tell("It is the finest tea you have ever tasted. It has almost made this entire misadventure seem worthwhile. You experience several moments of complete happiness and relaxation.");
    (await ANTI_LITTER("cup"));
    return crlf();
  } else if (isVerb(V.POUR, V.THROW)) {
    return await LIQUID_SPILL();
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell(S(g.IT_LOOKS_LIKE), " it has even more", S(g.BROWNIAN), " than ", D(SUBSTITUTE), "!");
    if (g.PRSO == g.BROWNIAN_SOURCE) {
      tell(" ");
      await PERFORM(V.EXAMINE, DANGLY_BIT);
      return true;
    } else {
      return crlf();
    }
  } else {
    return false;
  }
}

async function NO_TEA_F() {
  if (isVerb(V.TAKE, V.PICK_UP, V.DROP) && (g.PRSO == NO_TEA) && !(hasFlag(PARTICLE, MUNGEDBIT))) {
    tell("Your common sense tells you that you can't do that.\n");
    return true;
  } else if (isVerb(V.TAKE, V.PICK_UP) && (g.PRSO == NO_TEA) && !g.HOLDING_NO_TEA) {
    g.HOLDING_NO_TEA = true;
    tell("no tea: Taken.\n");
    return true;
  } else if (isVerb(V.SHOW, V.GIVE) && (g.PRSI == SCREENING_DOOR)) {
    return false;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == GUIDE)) {
    return false;
  } else if (isVerb(V.ASK_FOR) && (g.PRSO == NUTRIMAT)) {
    await PERFORM(V.RUB, PAD);
    return true;
  } else {
    tell("You're talking complete nonsense; pull yourself together.\n");
    return true;
  }
}

async function TEA_PRINT(obj) {
  if (!(obj == TEA || obj == NO_TEA)) {
    return true;
  } else if (isVerb(V.SHOW)) {
    return true;
  } else if (obj == TEA) {
    if (isVerb(V.TAKE)) {
      if (await HELD$(TEA)) {
        return true;
      } else if (g.PRSI && !(g.PRSI == loc(g.PRSO))) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP) && !g.HOLDING_NO_TEA) {
      return false;
    } else {
      return false;
    }
  } else if ((obj == NO_TEA) && isVerb(V.TAKE) && !g.HOLDING_NO_TEA) {
    return false;
  } else {
    return true;
  }
}

async function THUMB_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The ", D(THUMB), " is shaped like a small fist with an extended thumb. Various lights along its \"knuckles\" are currently ");
    if ((loc(FLEET) == g.HERE) || (g.HERE == AIRLOCK || g.HERE == INSIDE_WHALE)) {
      tell("blinking wildly, indicating a spaceship in the vicinity");
    } else {
      tell("dark");
    }
    tell(". It has two small buttons, a red one labelled \"Call Engineer\" and a green one labelled \"Hitchhike.\"");
    await FINE_PRODUCT();
    tell(" Affixed to the Thumb is a lifetime ", D(GUARANTEE), ".\n");
    return true;
  } else if (isVerb(V.TAKE) && (g.IDENTITY_FLAG == FORD) && (loc(FLEET) == g.HERE) && !(loc(THUMB) == SATCHEL)) {
    tell(S(g.DRIVEN_BACK), "\n");
    return true;
  } else if (isVerb(V.OPEN, V.CLOSE, V.LOOK_INSIDE)) {
    tell("Impossible.\n");
    return true;
  } else {
    return false;
  }
}

async function RED_BUTTON_F() {
  if (isVerb(V.PUSH)) {
    if (!(await HELD$(THUMB))) {
      await PERFORM(V.PUSH, GREEN_BUTTON);
      return true;
    } else if (loc(ENGINEER) == g.HERE) {
      tell("Another ", D(ENGINEER), " zips up, spots the first one, looks confused, and leaves again.\n");
      return true;
    } else {
      move(ENGINEER, g.HERE);
      move(BIKE, g.HERE);
      enable(await QUEUE(I_ENGINEER.id, 2));
      tell("With a screech of ion brakes a ", S(g.SCC), " Repair Robot pulls up on a bike from out of the Sub-Etha.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GREEN_BUTTON_F() {
  if (isVerb(V.PUSH)) {
    if (!(await HELD$(THUMB))) {
      tell(S(g.NOT_HOLDING), " the ", D(THUMB), ".\n");
      return g.P_IT_OBJECT = THUMB;
    } else if ((g.IDENTITY_FLAG == FORD) && (loc(FLEET) == g.HERE)) {
      move(THUMB, g.HERE);
      tell(S(g.THUMB_FUMBLE), "\n");
      return true;
    } else if (hasFlag(THUMB, MUNGEDBIT)) {
      tell("The", S(g.THUMB_CLICKS), "\n");
      return true;
    } else if (loc(FLEET) == g.HERE) {
      if (g.DRUNK_LEVEL == 3) {
        tell("Lights whirl sickeningly around your head, the ground arches away beneath your feet, and every atom of your being is scrambled, an experience you're probably going to have to get used to. You are in...\n\n");
        await LEAVE_EARTH();
        return await GOTO(DARK);
      } else {
        tell("A", S(g.BEAM));
        (await JIGS_UP(" is certainly a shock to the system. Too bad you didn't consume enough alcohol to withstand it."));
        return true;
      }
    } else if (g.HERE == AIRLOCK || g.HERE == INSIDE_WHALE) {
      tell("Every molecule in your body gets pulled away from every other molecule. Then suddenly they snap back together again like elastic, and you find, with a dizzy head and very sore molecules, that you are in...\n\n");
      g.HEART_PROB = 100;
      return await GOTO(DARK);
    } else {
      setFlag(THUMB, MUNGEDBIT);
      tell("The Thumb winks and flashes for a second. Nothing further happens.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function GUARANTEE_F() {
  if (isVerb(V.READ, V.EXAMINE)) {
    tell("The lifetime ", D(GUARANTEE), " states that the Thumb will be repaired on site by trained ", S(g.SCC), " Field Engineers.\n");
    return true;
  } else {
    return false;
  }
}

async function ENGINEER_F() {
  if (ENGINEER == g.WINNER) {
    enable(await QUEUE(I_ENGINEER.id, 2));
    if (isVerb(V.TELL_ABOUT) && (g.PRSO == ME)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.ASK_ABOUT, ENGINEER, g.PRSI);
      g.WINNER = ENGINEER;
      return true;
    } else if (isVerb(V.HELLO)) {
      g.WINNER = PROTAGONIST;
      await PERFORM(V.HELLO, ENGINEER);
      g.WINNER = ENGINEER;
      return true;
    } else if (isVerb(V.REPAIR) && (g.PRSO == THUMB)) {
      if (loc(THUMB) == ENGINEER) {
        tell("\"I'm doing my best...\"\n");
        return true;
      }
      g.WINNER = PROTAGONIST;
      move(THUMB, PROTAGONIST);
      await PERFORM(V.GIVE, THUMB, ENGINEER);
      g.WINNER = ENGINEER;
      return true;
    } else if (isVerb(V.REPAIR)) {
      tell("\"I repair only ", D(THUMB), "s!\"\n");
      return true;
    } else if (isVerb(V.YES) && (g.AWAITING_REPLY == 12)) {
      return await V_YES();
    } else if (isVerb(V.NO) && (g.AWAITING_REPLY == 12)) {
      return await V_NO();
    } else {
      tell("\"Can't chat, pal, I'm attending to an important repair call.\"\n");
      return await FUCKING_CLEAR();
    }
  } else if (isVerb(V.GIVE, V.SHOW) && (g.PRSO == THUMB)) {
    if (hasFlag(THUMB, MUNGEDBIT)) {
      enable(await QUEUE(I_ENGINEER.id, 2));
      g.THUMB_SHOWN = 1;
      move(THUMB, ENGINEER);
      tell("The ", D(ENGINEER), " takes it, looks at it with horror, shakes his head, sighs, and says \"Who sold you this then?\"\n\n");
      print(">");
      await read(g.P_INBUF, g.P_LEXV);
      tell("The ", D(ENGINEER), " ignores your reply and shakes the Thumb despondently. \"This is a model 13X,\" he says. \"Not meant for this sort of job. Anyway, it's discontinued. Can't get the parts.\"\n");
      return true;
    } else {
      move(THUMB, PROTAGONIST);
      await ENGINEER_LEAVE();
      tell("The ", D(ENGINEER), " takes the Thumb, shakes it, looks it up and down. \"Seems to be working OK to me. Unusual for a 13X.\" He hands it back and", S(g.ROARS_OFF), ".\n");
      return true;
    }
  } else if (isVerb(V.GIVE, V.SHOW) && (g.PRSO == GUARANTEE)) {
    if (!(hasFlag(THUMB, MUNGEDBIT))) {
      await PERFORM(V.GIVE, THUMB, ENGINEER);
      return true;
    }
    clearFlag(THUMB, MUNGEDBIT);
    await ENGINEER_LEAVE();
    move(THUMB, PROTAGONIST);
    if (g.THUMB_SHOWN == 0) {
      tell("The ", D(ENGINEER), " looks quizzically at the ", D(GUARANTEE), " and says it's expired but he'll see what he can do. ", S(g.FIDDLES), "\"Can't promise anything.\" He", S(g.ROARS_OFF), ".\n");
      return true;
    } else {
      g.THUMB_SHOWN = 0;
      tell("The ", D(ENGINEER), " looks at it sceptically. \"Guaranteed to work normally for life,\" he mutters. \"Well, it's perfectly normal for a 13X to break down. And this one's reached the end of its life anyway. But I'll see what I can do.\"\n\n", S(g.FIDDLES), "\"Best I can do for a 13X on an expired ", D(GUARANTEE), ",\" he says. \"Can't promise anything.\" He", S(g.ROARS_OFF), ".\n");
      return true;
    }
  } else {
    return false;
  }
}

async function ENGINEER_LEAVE() {
  if (loc(THUMB) == ENGINEER) {
    if (loc(ENGINEER) == g.HERE) {
      move(THUMB, PROTAGONIST);
    } else {
      move(THUMB, loc(ENGINEER));
    }
  }
  move(ENGINEER, LOCAL_GLOBALS);
  move(BIKE, LOCAL_GLOBALS);
  disable(await INT(I_ENGINEER.id));
  g.THUMB_SHOWN = 0;
  return g.ENGINEER_COUNTER = 0;
}

async function I_ENGINEER() {
  enable(await QUEUE(I_ENGINEER.id, -1));
  g.ENGINEER_COUNTER = g.ENGINEER_COUNTER + 1;
  if (!(loc(ENGINEER) == g.HERE)) {
    await ENGINEER_LEAVE();
    return false;
  }
  crlf();
  if (g.THUMB_SHOWN == 1) {
    g.THUMB_SHOWN = 2;
    tell("The ", D(ENGINEER), " ignores you completely. \"See, this is the model with the 5kz booster,\" he says. \"Hopeless.\" He shakes his head grimly.\n");
    return true;
  } else if (g.THUMB_SHOWN == 2) {
    tell("The ", D(ENGINEER), " ignores you. \"What you want, you see, is one of the new Mk7's. Only you can't get them. Out of stock till Zarkmas. Sorry.\" He");
    if (loc(THUMB) == ENGINEER) {
      tell(" gives the defunct Thumb back and");
    }
    await ENGINEER_LEAVE();
    tell(S(g.ROARS_OFF), ".\n");
    return true;
  } else if (g.ENGINEER_COUNTER == 1) {
    g.AWAITING_REPLY = 12;
    enable(await QUEUE(I_REPLY.id, 2));
    tell("The ", D(ENGINEER), " looks around. \"Somebody call the repair service?\"\n");
    return true;
  } else if (g.ENGINEER_COUNTER == 2) {
    tell("The ", D(ENGINEER), " looks impatient and guns the throttle of his cycle.\n");
    return true;
  } else {
    await ENGINEER_LEAVE();
    tell("\"Probably a kid playing around with someone else's Thumb,\" grumbles the ", D(ENGINEER), " and", S(g.ROARS_OFF), ".\n");
    return true;
  }
}

async function GUIDE_DESCFCN(x = 0) {
  tell("There is a copy of ", S(g.GUIDE_NAME), " here.\n");
  return true;
}

async function GUIDE_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The Guide is a Mark II model. Its only resemblance to the Mark IV pictured in the brochure in your game package is the large, friendly \"Don't Panic!\" on its cover.\n\nThe Guide is a Sub-Etha Relay. You can use it to tap information from a huge and distant data bank by consulting the Guide about some item or subject.\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT) && (g.PRSO == GUIDE)) {
    if (hasFlag(TOWEL, WORNBIT)) {
      tell(S(g.WITH_TOWEL), "\n");
      return true;
    } else if (g.PRSI == ACCESS_SPACE) {
      tell("Suddenly, agents of the ", S(g.AGENCY), " pop in using Sub-Etha belts, rough you up a bit, tell you there's no such thing as the ", S(g.AGENCY), " and never to consult ", D(GUIDE), " about the ", S(g.AGENCY), " again; then they leave.\n");
      return true;
    }
    tell("The Guide checks through its Sub-Etha-Net database and eventually comes up with the following entry:\n\n");
    if (g.PRSI == GUIDE) {
      tell(D(GUIDE), " is a wholly remarkable product.", S(g.ALREADY_KNOW_THAT), "\n");
      return true;
    } else if (g.PRSI == DANGLY_BIT || g.PRSI == SMALL_RECEPTACLE || g.PRSI == LARGE_PLUG || g.PRSI == SMALL_PLUG || g.PRSI == GREEN_BUTTON || g.PRSI == RED_BUTTON) {
      tell("Part of");
      if ((g.PRSI == LARGE_PLUG) && !(loc(LARGE_PLUG) == SPARE_DRIVE)) {
        await ARTICLE(SPARE_DRIVE);
      } else {
        await ARTICLE(loc(g.PRSI));
      }
      tell(".\n");
      return true;
    } else if (g.PRSI == WAR_CHAMBER) {
      tell("If you have to consult the Guide about that, you're probably in serious shape. Consult a medic instead.\n");
      return true;
    } else if (g.PRSI == DAMOGRAN) {
      tell(D(DAMOGRAN), " is a planet whose surface is mostly water. It is a favourite spot for Presidential dedication ceremonies", S(g.ALSO_SEE), "France.\n");
      return true;
    } else if (g.PRSI == CLIFF) {
      tell("France is the largest landmass on the planet ", D(DAMOGRAN), ".\n");
      return true;
    } else if (g.PRSI == HEART_OF_GOLD) {
      tell("There is absolutely no such spaceship as ", D(HEART_OF_GOLD), " and anything you've ever read in this spot to the contrary was just a prank.\n   -- ", S(g.AGENCY), "\n");
      return true;
    } else if (g.PRSI == POETRY) {
      tell(D(POETRY), " is so awful that even the Sarkopsi of Burphon XII, whose religion strictly forbids the taking of one's life, consider suicide a preferable alternative to a ", D(POETRY), " reading.\n");
      return true;
    } else if (g.PRSI == VOGON_CAPTAIN || g.PRSI == FLEET) {
      tell("Vogons, whose specialties are bureaucracy and planet-smashing, are the most unpleasant race in the Galaxy. They wouldn't think twice about throwing someone into space, and wouldn't lift a finger to save their own grandmother from the ", D(BEAST), S(g.ALSO_SEE), D(POETRY), " and the ", D(BEAST), ".\n");
      return true;
    } else if (g.PRSI == BEER || g.PRSI == PUB) {
      tell("Alcohol, in addition to its familiar enjoyable effects, also helps cushion the shock of", S(g.BEAM), "s.\n");
      return true;
    } else if (g.PRSI == BRIDGE) {
      tell("The best randomness generator is simple", S(g.BROWNIAN), ". Any hot gas or liquid is a good source.\n");
      return true;
    } else if (g.PRSI == GALLEY) {
      tell("The ", S(g.SCC), " incompetently produces a wide range of inefficient and unreliable high-tech machinery. However, thanks to SCC's ruthless marketing division, this junk accounts for over 95% of the high-tech machinery sold in the Galaxy. (SCC's marketing division will be the first against the wall when the revolution comes.)\n");
      return true;
    } else if (g.PRSI == PANTRY) {
      tell("Thirty million generations of philosophers have debated the definition of intelligence. The most popular definition appears in the ", S(g.SCC), " android manuals: \"Intelligence is the ability to reconcile totally contradictory situations without going completely bonkers -- for example, having a stomach ache and not having a stomach ache at the same time, holding a hole without the doughnut, having good luck and bad luck simultaneously, or seeing a real estate agent waive his fee.\"\n");
      return true;
    } else if (g.PRSI == SCREENING_DOOR) {
      tell("These ", S(g.SCC), " doors screen visitors for such qualities as intelligence and ability to time travel", S(g.ALSO_SEE), S(g.SCC), ", ", S(g.GPP), ", Intelligence, and Time Travel.\n");
      return true;
    } else if (g.PRSI == HATCHWAY || g.PRSI == MARVIN || g.PRSI == EDDIE) {
      tell(S(g.GPP), " are a misguided attempt by the ", S(g.SCC), " to make their machines behave more like people. Among the more miserable failures: paranoid-depressive robots and over-protective computers.\n");
      return true;
    } else if (g.PRSI == DARK) {
      tell("A must for the serious hitchhiker, peril-sensitive sunglasses darken at the first hint of danger, thus shielding the wearer from seeing anything alarming. Recommended brand: Joo Janta.\n");
      return true;
    } else if (g.PRSI == RAMP) {
      tell("According to legend, Magrathea was a planet that amassed incredible wealth by manufacturing ", D(OTHER_PLANETS), ". The legends also mention it as the setting of the very eagerly awaited second Infocom Hitchhiker's game.\n");
      return true;
    } else if (g.PRSI == ENGINE_ROOM || g.PRSI == MAIN_DRIVE || g.PRSI == SPARE_DRIVE) {
      tell("Scientists have long known how to produce FINITE amounts of improbability, using a ", S(g.FIG), ", an ", D(PLOTTER), " and a good source of", S(g.BROWNIAN), ". Recently, however, they have learned to generate INFINITE amounts, thanks to the invention of the In", S(g.FIG), ". It is rumored that an", S(g.IID), ", based on this new generator, is currently under development", S(g.ALSO_SEE), D(PLOTTER), " and", S(g.BROWNIAN), ".\n");
      return true;
    } else if (g.PRSI == PLOTTER) {
      tell("The ", D(PLOTTER), " is one of the primary application devices of Improbability Physics.\n");
      return true;
    } else if (g.PRSI == PEANUTS || g.PRSI == HOLD) {
      tell("Sources of protein, such as the common peanut, are carried by all serious hitchhikers. Protein loss occurs in", S(g.BEAM), "s and you will become groggy unless you replace it immediately.\n");
      return true;
    } else if (g.PRSI == NUTRIMAT || g.PRSI == NUT_COM_INTERFACE) {
      tell("A typically unreliable ", S(g.SCC), " product, the ", D(NUTRIMAT), " analyses the user's neural paths to provide the (supposedly) ideal offering. Its computing power is frankly abysmal, so the optional computer interface is a good thing to go for.");
      return crlf();
    } else if (g.PRSI == POCKET_FLUFF || g.PRSI == JACKET_FLUFF || g.PRSI == SATCHEL_FLUFF || g.PRSI == CUSHION_FLUFF) {
      tell("Fluff is interesting stuff: a deadly poison on Bodega Minor, the diet staple of Frazelon V, the unit of currency on the moons of the Blurfoid system, and the major crop of the laundry supplies planet, Blastus III.\nOne ancient legend claims that four pieces of fluff lie scattered around the Galaxy; each forming one-quarter of the seedling of a tree with amazing properties, the sole survivor of the tropical planet Fuzzbol (Footnote 8).\nThe ultimate source of fluff is still a mystery, with the scientific community torn between the Big Lint Bang theory and the White Lint Hole theory.\n");
      return true;
    } else if ((g.PRSI == ZAPHOD) || ((g.PRSI == ME) && (g.IDENTITY_FLAG == ZAPHOD))) {
      tell(D(ZAPHOD), " is the current", S(g.PRESIDENT), ".\n");
      return true;
    } else if (g.PRSI == BABEL_FISH) {
      tell("A mind-bogglingly improbable creature. A ", D(BABEL_FISH), ", when placed in one's ear, allows one to understand any language.\n");
      return true;
    } else if (g.PRSI == TOWEL) {
      tell("A towel is the most useful thing (besides the Guide) a Galactic hitchhiker can have. Its uses include travel, combat, communications, protection from the elements, hand-drying and reassurance. Towels have great symbolic value, with many associated points of honour. Never mock the towel of another, even if it has little pink and blue flowers on it. Never do something to somebody else's towel that you would not want them to do to yours. And, if you borrow the towel of another, you MUST return it before leaving their world.\n");
      return true;
    } else if (g.PRSI == THUMB || g.PRSI == GUARANTEE) {
      tell("The Electronic Sub-Etha Auto Hitching Thumb is a wonderful thing, but should not be mistreated. If used while a ship is near, you will be transported there. If no ship is in the vicinity, you will place a heavy strain on the Thumb's logic circuits, which could lead to malfunction. The Thumb carries the usual ", S(g.SCC), " lifetime ", D(GUARANTEE), "s.\n");
      return true;
    } else if (g.PRSI == MINERAL_WATER) {
      tell("A strong body of opinion holds that this is not water at all, despite the claims on the label about how pure the spring is, and all that tosh about sparkling babbling brooks and so on. There is something highly suspect about the water on Santraginus Five, as anyone who's ever met any of their fish will tell you.\n");
      return true;
    } else if (g.PRSI == BEAST) {
      tell("The ", D(BEAST), " is a mind-bogglingly stupid animal. It has almost no capacity for learning from experience and is therefore surprised by virtually everything that happens to it. Here is an example of how stupid it is: it thinks that if you can't see it, it can't see you.\nIts behaviour would be quite endearing if it wasn't spoilt by this one thing: it is the most violently carnivorous creature in the Galaxy. Avoid, avoid, avoid.\n");
      return true;
    } else if (g.PRSI == FRONT_PORCH) {
      tell("A thoroughly unpleasant means of travelling which involves tearing you apart in one place and slamming you back together in another. (Of course, it's better than the older method, where disassembled people would be transmitted down phone lines and arrive in a garbled and sometimes completely disconnected state.) You should have a drink or two or three before going through one", S(g.ALSO_SEE), "Galaxia Woonbeam, Alcohol, and Protein.\n");
      return true;
    } else if (g.PRSI == FRONT_OF_HOUSE) {
      tell("Galaxia Woonbeam is the author of \"Slimmer's Guide to Weightloss During Matter Disassembly Transition.\" This text is currently the subject of the biggest suit for criminal negligence damages in history and is unavailable at this time.\n");
      return true;
    } else if (g.PRSI == ENTRY_BAY) {
      tell("The best drink in existence; somewhat like having your brains smashed out by a slice of lemon wrapped around a large gold brick.\n");
      return true;
    } else if (g.PRSI == THIRD_PLANET || g.PRSI == MAZE) {
      tell("Mostly harmless.\n");
      return true;
    } else if (g.PRSI == COUNTRY_LANE) {
      tell(S(g.SPACE_TEXT), "\n");
      return true;
    } else if (hasFlag(g.PRSI, TOOLBIT)) {
      tell("The editor responsible for entries under this heading has been out to lunch for a couple of years but is expected back soon, at which point there will be rapid updates. Until then, don't panic, unless your situation is really a life or death one, in which case, sure, go ahead, panic.\n");
      return true;
    } else if (g.PRSI == BEDROOM || g.PRSI == RIFLES || g.PRSI == BLASTER || g.PRSI == TEA || g.PRSI == NO_TEA || g.PRSI == BEAST_GUN || g.PRSI == SUBSTITUTE || g.PRSI == AFT_CORRIDOR || g.PRSI == AIRLOCK || g.PRSI == INSIDE_WHALE) {
      tell("Sorry, that portion of our Sub-Etha database was accidentally deleted last night during a wild office party. The lost data will be restored as soon as we find someone who knows where the back-up tapes are kept, if indeed any are kept at all.\n");
      return true;
    } else {
      tell("That is one of the Great Unanswered Questions. For a list of the others, consult the Guide.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function CANT_SEE(obj) {
  tell("You can't see");
  if (!(await NAME$(obj))) {
    tell(" any");
  }
  if (obj == g.PRSO) {
    await PRSO_PRINT();
  } else {
    await PRSI_PRINT();
  }
  tell(" here.\n");
  return await FUCKING_CLEAR();
}

async function TELL_ME_HOW() {
  tell("You must tell me how to do that to");
  await ARTICLE(g.PRSO);
  tell(".\n");
  return true;
}

async function OUT_OF_FIRST(vehicle) {
  tell("You'll have to get out of the ", D(vehicle), " first.\n");
  return true;
}

async function PRIVATE(string) {
  tell("You can't. It's not yours. It's ", S(string), "'s and it's private.\n");
  return true;
}

async function NOT_VERY_GOOD(string) {
  tell("It's not a very good ", S(string), ", is it?\n");
  return true;
}

async function FACTOR(string) {
  tell(" at an improbability factor of 2 to the ", S(string), "th power to 1 against.");
  return true;
}

async function REMOVING_BIT() {
  tell("(removing the ", D(DANGLY_BIT), " first)\n");
  return true;
}

async function PART_OF() {
  tell("You can't --");
  await ARTICLE(g.PRSO, true);
  tell(" is an integral part of");
  await ARTICLE(loc(g.PRSO), true);
  tell(".\n");
  return true;
}

async function BUT_THAT_MAN(string) {
  tell("Pointing toward Prosser, ", S(string), " \"But that man ");
  if (g.HOUSE_DEMOLISHED) {
    tell("just knocked");
  } else {
    tell("wants to knock");
  }
  tell(" my house down!\"");
  return true;
}

async function CUSHION() {
  tell(" cushion your system against the coming shock of the", S(g.BEAM), ".");
  return true;
}

async function FINE_PRODUCT() {
  tell(" It bears a small label which reads \"Another fine product of the ", S(g.SCC), ".\"");
  return true;
}

async function MAKE_WAY_FOR() {
  tell(" a ", D(FLEET), " unexpectedly arrives and demolishes the Earth to make way for a new hyperspace bypass.\n");
  return true;
}

async function OWN_FEET() {
  tell("You are now on your feet.\n");
  return true;
}

